// Verify interest arithmetic: Oct 25 as-of basis and Nov 11 filing-date projection
const inv = [
  { id: 'J-4411', p: 68400.00, dueDaysOct25: 178 },
  { id: 'J-4452', p: 71250.00, dueDaysOct25: 147 },
  { id: 'J-4490', p: 66100.00, dueDaysOct25: 117 },
  { id: 'J-4533R', p: 71700.00, dueDaysOct25: 86 },  // 74,800 gross − 3,100 credit
  { id: 'J-4571', p: 59450.00, dueDaysOct25: 55 },
];
const r = (x) => Math.round(x * 100) / 100;

// Oct 25 as-of
let octInt = 0;
for (const i of inv) {
  const it = r(i.p * 0.01 * i.dueDaysOct25 / 30);
  octInt += it;
}
octInt = r(octInt);

// Nov 11 = 17 days after Oct 25 (Oct 25 -> Oct 31 = 6; + 11 = 17)
const gap = 17;
let novInt = 0; const lines = [];
for (const i of inv) {
  const d = i.dueDaysOct25 + gap;
  const it = r(i.p * 0.01 * d / 30);
  novInt += it;
  lines.push(`${i.id}: principal ${i.p.toFixed(2)} × 1% × ${d}/30 = ${it.toFixed(2)}`);
}
novInt = r(novInt);
const daily = r((336900 * 0.01) / 30);
const delta = r(daily * gap);

const principal4 = r(68400 + 71250 + 66100 + 59450);
const principal5 = r(principal4 + 71700);
const withConv = r(principal5 + 80000);
const grandOct = r(withConv + octInt);
const grandNov = r(withConv + novInt);

// C.6 small-claims test: smallest invoice
const smallest = 59450, smallestWithInt = r(59450 + 1089.92);

return {
  perOct: inv.map(i => ({ id: i.id, interest: r(i.p * 0.01 * i.dueDaysOct25 / 30) })),
  octInterestTotal: octInt,
  lines,
  novInterestTotal: novInt,
  deltaCheck: { daily, gap, delta, matches: r(novInt - octInt) === delta },
  principalSummary: { fourInvoices: principal4, plusNet4533R: principal5, plusConversions: withConv },
  grandTotals: { asOfOct25: grandOct, filingNov11Projection: grandNov },
  c6test: { smallest, smallestWithInt, cap: 25000, bar: smallest >= 25000 && smallestWithInt >= 25000 },
  projectionInvoicesOnly: r(principal5 + novInt)
};

